 @Test void explicitUndividedProjectAllowsThresholdComparison(){String scope="本项目不划分标段";EvidenceCorpus c=corpus(priceText("100","万元",scope,"人民币","含税"));java.util.List<cn.bidcheck.verification.engine.VerificationTypes.Fact> fs=checked(c,price(c,1,"100","万元",scope,"人民币","含税"));Rule r=new Rule("r","报价门槛","NUMBER","甲公司","price","<=","200","万元",cn.bidcheck.compat.Java8Api.mapOf("lot", scope, "currency", "人民币", "taxBasis", "含税", "amountBasis", "投标总报价"),"本项目不划分标段，甲公司人民币含税投标总报价不超过200万元","",cn.bidcheck.compat.Java8Api.listOf());assertEquals("PASS",new RuleEvaluator(fs,c,cn.bidcheck.compat.Java8Api.mapOf()).evaluate(r).status());}
 @Test void unitCannotBeBorrowedFromAnotherAmount(){EvidenceCorpus c=corpus("本项目甲公司第一标段人民币含税投标总报价：100元；注册资本：100万元");Fact f=price(c,1,"100","万元","第一标段","人民币","含税");assertTrue(new ProofVerifier().verify(json.valueToTree(cn.bidcheck.compat.Java8Api.mapOf("facts", cn.bidcheck.compat.Java8Api.listOf(f))),c.all).facts().isEmpty());}
 @Test void unsupportedCompositeNeverFallsThroughAsAll(){EvidenceCorpus c=corpus("资料");Rule child=rule("REFERENCE_TIME","","",cn.bidcheck.compat.Java8Api.mapOf(),"截止日期"),unsupported=new Rule("r","域外规则","UNSUPPORTED","","","","","",cn.bidcheck.compat.Java8Api.mapOf(),"域外规则","ALL",cn.bidcheck.compat.Java8Api.listOf(child));Decision d=new RuleEvaluator(cn.bidcheck.compat.Java8Api.listOf(),c,reference("BID_DEADLINE","2025-08-01")).evaluate(unsupported);assertEquals("UNDETERMINED",d.status());assertEquals("UNSUPPORTED_RULE",d.gaps().get(0).code());}
